def apply(T):
    a=T.s.find('const AV_DESC={'); b=T.s.find('};',a)
    assert a>0 and b>a
    T.s=T.s[:a]+'const AV_DESC='+json.dumps(AV,ensure_ascii=False)+T.s[b+1:]
